INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p483377-pyp002', 'stk-user5334', 'PYP 002', 'info', '{"desc": "والله وانا اخوك انا كاان عندي اختبار الاربعاء …\n\nصراحه السلايدات طويله … و المعلومات اللي فيها تافهه …! لكن اللي مصعبها انها انجلش و يضيع الوقت ترجمه …\n\nيعني اذا كان عندك معلومات اساسيه بالحاسب … ما يحتاج ذيك المذاكره … و اذا جا الاختبار ترجم السؤال اللي يجيك في قوقل و جاوب عليه … و هو مسموح لان المدرس شاف كم واحد يسويها و ما قال شي …\n\nبالتوفيق … لكن لا تعتمد ع كلامي !! يعني ذاكر و شد حيلك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pyp002/79218/6", "user": "user5334", "ts": 1256848558000, "tid": 79218, "pn": 6}}', 1256848558000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisal_19-pyp002', 'stk-faisal_19', 'PYP 002', 'doc', '{"docs": [{"id": "stk-dr-f99457", "n": "Dr. Ahmed Baqais", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PYP002 - 161\n\nالتحضير: كل كلاس\nطريقة الشرح: من بوربوينت القسم، المادة بشكل عام بسيطة وما فيها ذيك المعلومات الي تتطلب شرح.\nالكويزات: سهلة ومباشرة\nالمياجر: تفهم الدرس وتطبق معه صح تضمن الميجر ان شاء الله\nالفاينلات: ما فيه فاينل\nالقريد النهائي: A+ واخذت معاه A+ الحمدلله\nالصوت: واضح جداً.\n\nإضافات : المادة بشكل عام ما فيها شي ابداً كلها اساسيات ( الورد - البوربوينت - الاكسل ) + HTML ،الاستاذ متساعد بشكل كبير ويحاول يفهم كل الطلاب لكن للاسف كان فيه طلاب مهملين ويبون الاستاذ يدفهم كذا بدون شغل وهذا شي مرفوض! ، بعد ما يخلص شرح تطبق الدرس واذا خلصت تمشي ، انا كنت اخلص قبل 40 - 50 دقيقة من نهاية الكلاس، يسجل اني طبقت عشان المشاركة وامشي 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467477-pyp002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-ahmed-baqais/99457/14", "user": "Faisal_19", "ts": 1486070010000, "tid": 99457, "pn": 14}}]}', 1486070010000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chaos_is_a_ladder-pyp002', 'stk-chaos_is_a_ladder', 'PYP 002', 'doc', '{"docs": [{"id": "stk-dr-f99457", "n": "Dr. Ahmed Baqais", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PYP002 - 211\n\nالتحضير : يكتب اسمك بورقة بعد ما تخلص اللابوورك\n\nطريقة الشرح : شرح مناسب\n\nالكويزات : متوسطة الى سهله وهذي ميزة\n\nالتصحيح: جدا ممتاز\n\nالقريد النهائي: ِA\n\nالصوت: واضح\n\nإضافات : الكلاس يصير ممل لان المتيريل نفسه ممل بالنسبة لي، استفدت من شرح الدكتور في الاكسل لاني مو فاهمه اما بقية الاشياء كانت ممله جدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533527-pyp002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-ahmed-baqais/99457/16", "user": "chaos_is_a_ladder", "ts": 1642747433000, "tid": 99457, "pn": 16}}]}', 1642747433000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dr.6moh-pyp002', 'stk-dr.6moh', 'PYP 002', 'doc', '{"docs": [{"id": "stk-dr-f115389", "n": "Dr. Muhammad Akhlaq", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\n\nطبعا درست عنده pyp-002 في ترم 111\nالتحضير : تحضير بكل كلاس … عادي تجي باي وقت بالكلاس بس راح يحطك ليت\nطريقة الشرح : الشرح على البروجكتر … بصراحة … يشرح كل صغيرة وكبيرة … يعني يشرح بأمانة\nالكويزات : سهلة\nالمياجر: --\nالفاينلات : --\nالقريد النهائي: B+\nالصوت: بما انه هندي 🙂 فـ الآكسنت لك عليه … لكن يعتبر مقبول\nإضافات : مدرس حبوب ويهتم بمصلحه الطالب … نجحت عنده بـ a+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p985517-pyp002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-muhammad-akhlaq/115389/2", "user": "Dr.6moh", "ts": 1329175895000, "tid": 115389, "pn": 2}}]}', 1329175895000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rapls-pyp002', 'stk-rapls', 'PYP 002', 'doc', '{"docs": [{"id": "stk-dr-f118593", "n": "Dr. Akhtar Hussain", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "172 - PYP002\n\nالتحضير : يحضر بداية الكلاس , صارم ويقول كل شي اعطي فيه بونص الا الغياب .\n\nطريقة الشرح : شرحه ممتاز ويحاول يخلي الكل يشارك ويحاول ما يصير ممل , ودايمًا يسأل أسئلة بشكل عشوائي .\n\nالكويزات : عن طريق البلاكبورد , كانت متوسطة ويساعد الطلاب .\n\nالمياجر: ثلاث مياجر , يكون موجود يراقب ويساعد الطلاب ( يغششهم احيانًا 😆 )\n\nالفاينلات : -\n\nالقريد النهائي: A++\n\nالصوت: واضح ولغته مفهومة ويعرف عربي شوي .\n\nإضافات : الصراحة اول ما طلع اسمه في الجدول سالت عنه وسمعت انه سيئ ولكن من تجربتي معه افضل مدرس درسني في الأوريا , حبيب وأخلاق ويحب تجي الاوفس , على قد ما تجي على قد ما يرتفع قريدك , يحب يهايط بالطلاب لما يمتلي مكتبه ويحب يوري باقي الدكاترة اني مهتم بطلابي 😅 😆 , يطلب تاسك تسويه كل اسبوع او اسبوعين , سلمها اول باول ورح له بالمكتب وابشر ب الـ A+ .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498508-pyp002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-akhtar-hussain/118593/10", "user": "Rapls", "ts": 1535725737000, "tid": 118593, "pn": 10}}]}', 1535725737000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
